&lt;div class="highlight js-code-highlight"&gt;
&lt;pre class="highlight vue"&gt;&lt;code&gt;


import { ref, onMounted } from 'vue';
import { fetchProduct } from './api/products';
import type { Product } from './types/product';

interface ProductCardVaporProps {
  productId: string;
  priority?: boolean;
}

const props = defineProps&lt;span class="nt"&gt;&amp;lt;ProductCardVaporProps&amp;gt;&lt;/span&gt;();
const product = ref&lt;span class="nt"&gt;&amp;lt;Product&lt;/span&gt; &lt;span class="err"&gt;|&lt;/span&gt; &lt;span class="na"&gt;null&lt;/span&gt;&lt;span class="nt"&gt;&amp;gt;&lt;/span&gt;(null);
const loading = ref(true);
const error = ref&lt;span class="nt"&gt;&amp;lt;string&lt;/span&gt; &lt;span class="err"&gt;|&lt;/span&gt; &lt;span class="na"&gt;null&lt;/span&gt;&lt;span class="nt"&gt;&amp;gt;&lt;/span&gt;(null);

/**
 * Vapor Mode: No runtime virtual DOM, compiles to direct DOM operations
 * Data fetching can run on server (SSR) or client, no split required
 */
const loadProduct = async () =&amp;gt; {
  try {
    loading.value = true;
    error.value = null;
    // Fetch runs in same context as component, no server/client split
    const data = await fetchProduct(props.productId);

    // Validate product shape
    if (!data.id || !data.name || typeof data.price !== 'number') {
      throw new Error(`Invalid product data for ${props.productId}`);
    }
    product.value = data;
  } catch (err) {
    console.error(`Vapor: Failed to fetch product ${props.productId}`, err);
    error.value = `Product ${props.productId} unavailable`;
  } finally {
    loading.value = false;
  }
};

const addToCart = () =&amp;gt; {
  try {
    if (!product.value) return;
    const cart = JSON.parse(localStorage.getItem('cart') || '[]');
    cart.push(product.value.id);
    localStorage.setItem('cart', JSON.stringify(cart));
  } catch (err) {
    console.error('Failed to update cart', err);
    alert('Unable to add item to cart');
  }
};

// Load product on mount, works for SSR and client-side renders
onMounted(loadProduct);





/* Vapor Mode scopes styles at compile time, no runtime overhead */
.product-card {
  border: 1px solid #e5e7eb;
  border-radius: 8px;
  overflow: hidden;
  max-width: 320px;
}
.product-card__image {
  width: 100%;
  height: 192px;
  object-fit: cover;
}
.product-card__body {
  padding: 16px;
}
.product-card__title {
  font-size: 18px;
  font-weight: 600;
  margin-bottom: 8px;
}
.product-card__price {
  font-size: 16px;
  color: #10b981;
  font-weight: 700;
  margin-bottom: 12px;
}
.product-card__description {
  font-size: 14px;
  color: #6b7280;
  margin-bottom: 16px;
}
.product-card__cta {
  background: #3b82f6;
  color: white;
  border: none;
  padding: 8px 16px;
  border-radius: 4px;
  cursor: pointer;
  width: 100%;
}

